import{_ as d,o,c as t,a3 as c}from"./chunks/framework.C6R8kWFE.js";const u=JSON.parse('{"title":"代码生成","description":"","frontmatter":{},"headers":[],"relativePath":"backend/code-generation.md","filePath":"backend/code-generation.md","lastUpdated":1790859329000}'),a={name:"backend/code-generation.md"};function r(s,e,n,i,l,p){return o(),t("div",null,[...e[0]||(e[0]=[c(`<h1 id="代码生成" tabindex="-1">代码生成 <a class="header-anchor" href="#代码生成" aria-label="Permalink to &quot;代码生成&quot;">​</a></h1><p><code>XiHan.BasicApp.CodeGeneration</code> 是一等独立模块，做<strong>数据库优先（DbFirst）的全栈代码生成</strong>：扫描一张已有数据库表的结构 → 落成可编辑的表/列配置 → 用 Scriban 模板渲染出<strong>后端实体到前端页面</strong>的整套 CRUD 代码 → 预览、打 Zip 下载或受控落盘。目标是把&quot;加一张表就要抄一遍八个后端文件 + 三个前端文件&quot;的重复劳动一键铺开。</p><h2 id="模块全景" tabindex="-1">模块全景 <a class="header-anchor" href="#模块全景" aria-label="Permalink to &quot;模块全景&quot;">​</a></h2><p>生成链路由几个协作角色组成，职责单一、可替换：</p><table tabindex="0"><thead><tr><th>角色</th><th>类型</th><th>职责</th></tr></thead><tbody><tr><td>编排应用服务</td><td><code>CodeGenerationAppService</code></td><td>对外入口：权限、事务、DTO 转换、历史留痕；导入 → 预览 → 生成 → 下载</td></tr><tr><td>结构导入器</td><td><code>IDatabaseSchemaImporter</code> / <code>DatabaseSchemaImporter</code></td><td>DbFirst 扫描库表元信息（列名/类型/可空/主键）</td></tr><tr><td>类型映射器</td><td><code>ITypeMappingProvider</code> / <code>DefaultTypeMappingProvider</code></td><td>DB 列类型 → C# 类型 / TS 类型 + 默认表单控件 / 查询方式</td></tr><tr><td>生成引擎</td><td><code>ICodeGenerationEngine</code> / <code>CodeGenerationEngine</code></td><td>管线编排：建模 → 选模板 → 渲染 → 产出</td></tr><tr><td>模板渲染器</td><td><code>ITemplateRenderer</code> / <code>ScribanTemplateRenderer</code></td><td>用<strong>原生 Scriban</strong> 渲染模板（见下文约定）</td></tr><tr><td>渲染器解析器</td><td><code>ITemplateRendererResolver</code></td><td>按 <code>TemplateEngine</code> 选渲染器；当前仅 Scriban</td></tr><tr><td>打包器</td><td><code>IGeneratedArtifactPackager</code> / <code>ZipArtifactPackager</code></td><td>产物清单 → Zip 字节流</td></tr><tr><td>生成到项目</td><td><code>IGeneratedArtifactWriter</code> / <code>ProjectArtifactWriter</code></td><td>写进本仓库的后端模块项目与前端工程（位置由配置推导，默认关闭，路径越界拒绝）</td></tr></tbody></table><p>四张配置实体（均 <code>BasicAppFullAuditedEntity</code>，软删、多租户、审计俱全）：</p><table tabindex="0"><thead><tr><th>实体</th><th>表</th><th>作用</th></tr></thead><tbody><tr><td><code>SysCodeGenDataSource</code></td><td><code>Sys_CodeGen_DataSource</code></td><td>外部数据库连接凭证 + 连通性自检 + DbFirst 扫描，<code>SourceName</code> 全局唯一</td></tr><tr><td><code>SysCodeGenTable</code></td><td><code>Sys_CodeGen_Table</code></td><td>一张目标表的生成主配置，<code>TableName</code> 全局唯一</td></tr><tr><td><code>SysCodeGenTableColumn</code></td><td><code>Sys_CodeGen_TableColumn</code></td><td>列级配置（类型映射、表单控件、查询方式、字典三分）</td></tr><tr><td><code>SysCodeGenTemplate</code></td><td><code>Sys_CodeGen_Template</code></td><td>模板（Scriban 正文 + 文件名/路径表达式），<code>TemplateCode</code> 全局唯一</td></tr></tbody></table><p>生成历史另存 <code>SysCodeGenHistory</code>：每次执行生成——无论成败——都写一条留痕（批次号、耗时、文件数、总字节、操作人、失败原因）。</p><h2 id="三种生成模式" tabindex="-1">三种生成模式 <a class="header-anchor" href="#三种生成模式" aria-label="Permalink to &quot;三种生成模式&quot;">​</a></h2><p>由 <code>SysCodeGenTable.TemplateType</code>（枚举 <code>TemplateType</code>）决定，也是模板筛选的分组维度：</p><table tabindex="0"><thead><tr><th>模式</th><th>枚举</th><th>适用场景</th><th>关键配置字段</th></tr></thead><tbody><tr><td>单表</td><td><code>Single</code></td><td>扁平 CRUD（如岗位、字典项、普通业务表）</td><td>主键列</td></tr><tr><td>树形</td><td><code>Tree</code></td><td>自引用层级（如菜单、部门、地区）</td><td><code>TreeParentColumn</code>（父级字段）、<code>TreeNameColumn</code>（名称字段）</td></tr><tr><td>主从</td><td><code>MasterDetail</code></td><td>一主多从（如订单 + 订单明细）</td><td><code>MasterTableId</code>（主表配置）、<code>MasterForeignKey</code>（子表外键列）</td></tr></tbody></table><p>无显式指定模板编码时，引擎按表的 <code>TemplateType</code> 取该类型下的启用模板集（<code>GetEnabledByTypeAsync</code>）。模板<strong>不按业务模块过滤</strong>——CRUD 模板对所有模块通用，只按模板类型分组。</p><blockquote><p>树形/主从的结构字段（父级列、名称列、主表、外键）通过 <code>CodeGenerationContext.Options</code> 透出给模板（键为 <code>TreeParentColumn</code> / <code>MasterForeignKey</code> 等），模板按 <code>TemplateType</code> 消费。当前内置模板套件以单表为主，树/主从的上下文已就绪，模板可自行扩展。</p></blockquote><h2 id="全栈生成-从实体到前端页面" tabindex="-1">全栈生成：从实体到前端页面 <a class="header-anchor" href="#全栈生成-从实体到前端页面" aria-label="Permalink to &quot;全栈生成：从实体到前端页面&quot;">​</a></h2><p>一次生成铺开<strong>后端 16 件 + 前端 7 件</strong>的整套 CRUD，均为内置模板（<code>IsBuiltIn=true</code>，分组 <code>backend-crud</code> / <code>frontend-crud</code>）。</p><p>除页面 <code>index.vue</code> 外，每个产物都成对登记：<strong>自动侧</strong>重新生成时整体覆盖，<strong>手动侧</strong>仅首次创建、此后永不触碰。二者在语言层面拼接——C# 数据类经 <code>partial</code> 合并，行为类经抽象基类与派生类继承，前端经 re-export / transform 组合。所以改表结构重新生成不会冲掉手写实现。</p><table tabindex="0"><thead><tr><th>模板编码</th><th>自动侧（每次覆盖）</th><th>手动侧（仅首次创建）</th></tr></thead><tbody><tr><td><code>backend.entity</code></td><td><code>{{ ClassName }}.Generated.cs</code></td><td><code>{{ ClassName }}.cs</code></td></tr><tr><td><code>backend.dtos</code></td><td><code>{{ ClassName }}Dtos.Generated.cs</code></td><td><code>{{ ClassName }}Dtos.cs</code></td></tr><tr><td><code>backend.irepository</code></td><td><code>I{{ ClassName }}Repository.Generated.cs</code></td><td><code>I{{ ClassName }}Repository.cs</code></td></tr><tr><td><code>backend.repository</code></td><td><code>{{ ClassName }}Repository.Generated.cs</code></td><td><code>{{ ClassName }}Repository.cs</code></td></tr><tr><td><code>backend.contracts</code></td><td><code>I{{ ClassName }}Contracts.Generated.cs</code></td><td><code>I{{ ClassName }}Contracts.cs</code></td></tr><tr><td><code>backend.mapper</code></td><td><code>{{ ClassName }}ApplicationMapper.Generated.cs</code></td><td><code>{{ ClassName }}ApplicationMapper.cs</code></td></tr><tr><td><code>backend.appservice</code></td><td><code>{{ ClassName }}AppServiceBase.Generated.cs</code></td><td><code>{{ ClassName }}AppService.cs</code></td></tr><tr><td><code>backend.queryservice</code></td><td><code>{{ ClassName }}QueryServiceBase.Generated.cs</code></td><td><code>{{ ClassName }}QueryService.cs</code></td></tr><tr><td><code>frontend.types</code></td><td><code>{{ ClassNameKebab }}.types.generated.ts</code></td><td><code>{{ ClassNameKebab }}.types.ts</code></td></tr><tr><td><code>frontend.api</code></td><td><code>{{ ClassNameKebab }}.generated.ts</code></td><td><code>{{ ClassNameKebab }}.ts</code></td></tr><tr><td><code>frontend.schema</code></td><td><code>{{ ClassNameKebab }}.schema.generated.ts</code></td><td><code>{{ ClassNameKebab }}.schema.ts</code></td></tr><tr><td><code>frontend.page</code></td><td>——</td><td><code>index.vue</code></td></tr></tbody></table><p>页面与 schema 按 <code>TemplateType</code> 分化，各自另有一套登记：单表 <code>frontend.schema</code> / <code>frontend.page</code>，主子表 <code>frontend.schema.masterdetail</code> / <code>frontend.page.masterdetail</code>，树表 <code>frontend.schema.tree</code> / <code>frontend.page.tree</code>。产物文件名相同，一张表只会命中其中一套。</p><p>前端产物落到 <code>src/api/modules/&lt;module&gt;/</code> 与 <code>src/views/&lt;module&gt;/&lt;class-kebab&gt;/</code>（路径表达式里 <code>ModuleName</code> 会 <code>string.downcase</code>）。生成的页面与手写页面同构：<code>SchemaPage</code> 驱动列表与搜索，<code>XEditModal</code> + <code>XhFormRoot</code> 承载表单弹窗，控件取 <code>~/components</code> 的 <code>XInput</code> / <code>XSelect</code> / <code>XNumberInput</code> / <code>XTreeSelect</code>，提示走 <code>~/composables</code> 的 <code>toast</code>，枚举下拉走 <code>useEnumOptions</code>。文案为中文字面量，接 i18n 需自行替换。</p><p>除模板产物外，引擎每次还追加<strong>二阶产物</strong>（后端接线，路径相对后端模块项目根）：</p><ul><li><code>Domain/Permissions/{{ClassName}}PermissionCodes.cs</code>——权限码常量类（资源段取表名，<code>{资源}:{操作}</code> 两段式）。</li><li><code>Domain/Permissions/{{ClassName}}PermissionDefinitions.cs</code>——权限定义片段。</li><li><code>Infrastructure/Seeders/{{ClassName}}PermissionCatalog.cs</code> 与 <code>Infrastructure/Seeders/{{ClassName}}MenuPages.cs</code>——权限目录登记与菜单登记（总是覆盖，随包含操作、父菜单推导）。它们实现 <code>IPermissionCatalogContribution</code> / <code>IMenuPageContribution</code> 并按约定注册，由 SaaS 的汇总种子在权限目录、菜单两个阶段最后统一写入：不需要 <code>AddDataSeeder</code>，也没有种子顺序号。页面挂在表配置所选的「父菜单」下（只能选平台目录，按菜单码挂靠），未选即顶级菜单。</li><li><code>_GeneratedMenuPermission/{{ClassName}}PageRegistry.snippet.txt</code>——<code>PageDescriptor</code> / <code>ButtonDescriptor</code> 粘贴片段（并进模块自己的页面登记表时用，与菜单登记二选一）。</li><li><code>_GeneratedMenuPermission/README.md</code>——落地说明：权限码表、按钮→权限码映射、<code>SysMenu</code> 菜单规格与生效步骤（重启后端即由启动播种写入）。</li></ul><div class="tip custom-block"><p class="custom-block-title">从旧版本升级</p><p>前端模板此前产出的是 naive-ui 页面，现已整体迁到 XiHan.UI。已生成过代码的工程重新生成时：</p><ul><li><code>{kebab}.generated.ts</code> 的导出由 <code>xxxBaseManagementApi</code> 改名为 <code>xxxBaseApi</code>，而 <code>{kebab}.ts</code> 与 <code>index.vue</code> 是仅首次创建的手动文件、不会被覆盖，需手工把这两处的 <code>xxxManagementApi</code> / <code>xxxBaseManagementApi</code> 改成 <code>xxxApi</code> / <code>xxxBaseApi</code>。</li><li>旧 <code>index.vue</code> 引用的 <code>naive-ui</code> 与旧 schema 里的 <code>scrollX</code> 在当前前端都已不存在，那些文件本来就编译不过，建议删掉后重新生成。</li><li>bigint 列的 TS 类型由 <code>number</code> 改为 <code>string</code>（后端 <code>LongJsonConverter</code> 把 long 全部序列化为字符串）。存量表配置<strong>不用管</strong>：渲染期会按 C# 类型归一化，库里存着 <code>ts_type=&#39;number&#39;</code> 也照样产出正确的产物。升级脚本 <code>UpdateScripts/4.0.4</code> 只是顺带把库里的配置刷成一致，好让列配置界面显示的类型与实际产物对得上。</li></ul></div><div class="warning custom-block"><p class="custom-block-title">按钮码必须先落到 PageRegistry</p><p>生成页面的行/页面操作用 <code>permission: &#39;{页面码}.{按钮键}&#39;</code> 门控，这是服务端下发的<strong>按钮码</strong>。 把 <code>{{ClassName}}PageRegistry.snippet.txt</code> 里的 <code>ButtonDescriptor</code> 条目粘进 <code>PageRegistry.Buttons</code> 之前， 这些按钮不会显示，前端 <code>view-permission-hygiene</code> 门禁也会逐条列出未登记的码并判红。</p></div><blockquote><p>二阶产物是<strong>待并入源码的代码片段，不是运行时写库</strong>。这符合 BasicApp 的单一事实源 + 菜单即绑约定：把片段并入源码后，全新库由 Seeder 初始化；存量库还要把必要的数据变化纳入同版本 <code>UpdateScripts</code>。</p></blockquote><h3 id="表单控件的取值口径" tabindex="-1">表单控件的取值口径 <a class="header-anchor" href="#表单控件的取值口径" aria-label="Permalink to &quot;表单控件的取值口径&quot;">​</a></h3><ul><li>纯日期列（<code>date</code>）用 <code>XDatePicker</code>，按本地年月日（<code>yyyy-MM-dd</code>）提交，不会因时区换算退掉一天。</li><li>日期时间列（<code>datetime</code> / <code>timestamp</code> / <code>datetimeoffset</code>）用带时刻的 <code>XDatePicker show-time</code>，精确到分，按本地时间文本（<code>yyyy-MM-dd HH:mm:ss</code>）提交，与后端下发、导入的口径一致。</li><li>数字列用 <code>XNumberInput</code>：整数列 <code>:precision=&quot;0&quot;</code>，输入的小数直接回舍，不会因 1.5 让整单 400；<code>decimal</code> 列按列定义的小数位；浮点列不限。</li><li>文本列带上列定义的长度 <code>:max-length</code>，文本域同时显示字数；DTO 不校验长度，超长原本要到落库才报错。</li><li>关联表列的候选随目标表增长：表单用可输入筛选的 <code>XCombobox</code>，搜索区的字段标 <code>searchFilterable</code> 同样可输入筛选，都在取回的全量选项里本地筛；字典、枚举、常量下拉仍是 <code>XSelect</code>，关联树仍是树形下拉。已生成的页面重新生成后搜索区随 <code>schema.generated.ts</code> 自动换上，表单在 <code>index.vue</code> 里，想要可自行把该列的 <code>XSelect</code> 换成 <code>XCombobox</code>。</li><li>时间列（<code>time</code>）没有对应的选择器，仍是文本框 + <code>HH:mm(:ss)</code> 校验；二进制列用文本框承载 Base64，接真实上传需自行替换成上传组件。</li></ul><div class="warning custom-block"><p class="custom-block-title">5.4.2 及更早版本生成的页面</p><p><code>{kebab}.schema.generated.ts</code> 每次覆盖，<code>index.vue</code> 只首次创建。含日期时间列的表重新生成后，表单模型里该字段变为 <code>number | null</code>（时间戳），而旧 <code>index.vue</code> 仍用文本框承载，类型检查会报错。按新模板手工迁移旧 <code>index.vue</code>：</p><ul><li>控件换成 <code>&lt;XDatePicker v-model:value=&quot;form.xxx&quot; clearable show-time /&gt;</code>；</li><li>回填改为 <code>xxx: src.xxx ? new Date(String(src.xxx).replace(&#39; &#39;, &#39;T&#39;)).getTime() : null</code>；</li><li>提交改为 <code>toDateTime(form.value.xxx)</code>（可空列 <code>form.value.xxx == null ? null : toDateTime(form.value.xxx)</code>），<code>toDateTime</code> 照抄新模板；</li><li>删掉 <code>DATE_TIME_PATTERN</code> 及其校验；整数列的 <code>Number.isInteger</code> 校验可换成数字框的 <code>:precision=&quot;0&quot;</code>。</li></ul><p>不含日期时间列的表不受影响。</p></div><h2 id="数据源与表结构" tabindex="-1">数据源与表结构 <a class="header-anchor" href="#数据源与表结构" aria-label="Permalink to &quot;数据源与表结构&quot;">​</a></h2><h3 id="数据源" tabindex="-1">数据源 <a class="header-anchor" href="#数据源" aria-label="Permalink to &quot;数据源&quot;">​</a></h3><p><code>SysCodeGenDataSource</code> 管理外部数据库连接（主机/端口/库名/账号/加密密码或连接串），同时直接参与表结构扫描：</p><ul><li><code>DatabaseType</code> 标注连接方言，支持 <code>MySql</code> / <code>SqlServer</code> / <code>PostgreSql</code> / <code>Oracle</code> / <code>Sqlite</code>。</li><li>密码/连接串经 <code>AesHelper</code> 固定口令<strong>对称加密</strong>存储（<code>CodeGenDataSourceDomainService</code> 的 <code>EncryptSecret</code>/<code>DecryptSecret</code>）；<code>TestConnectionAsync</code> 用一个独立探测用的 <code>SqlSugarClient</code> 开关一次连接，回写 <code>LastTestTime</code> / <code>LastTestResult</code> / <code>LastTestMessage</code>。</li><li>保存（<code>CreateAsync</code> / <code>UpdateAsync</code>）<strong>不强制</strong>先测试连接通过；删除（<code>DeleteAsync</code>）当前<strong>未校验</strong>是否仍有 <code>SysCodeGenTable</code> 引用，删除前应先检查表配置引用。</li><li>导入弹窗调用 <code>codeGenDataSourceApi.options()</code> 加载数据源下拉；空值代表本系统主库，选择项的值是 <code>SysCodeGenDataSource.BasicId</code>。</li><li><code>DatabaseSchemaImporter</code> 首次使用外部数据源时解密连接信息，经 <code>IDynamicConnectionRegistrar</code> 按 <code>DataSourceId</code> 动态注册 SqlSugar 连接，再调用框架 <code>IDatabaseMetadataProvider</code> 扫描。</li><li>数据源不存在或停用时直接失败，<strong>不会静默回退主库</strong>；已注册连接会复用。</li></ul><p>导入后的 <code>SysCodeGenTable.DataSourceId</code> 会保留来源数据源，后续“同步表结构”和重新生成仍能定位同一外部库。数据源配置支持 <code>MySql</code> / <code>SqlServer</code> / <code>PostgreSql</code> / <code>Oracle</code> / <code>Sqlite</code>；这表示元数据扫描支持这些方言，不代表 BasicApp 自身的发布升级 SQL 已跨方言适配。</p><h3 id="表结构导入" tabindex="-1">表结构导入 <a class="header-anchor" href="#表结构导入" aria-label="Permalink to &quot;表结构导入&quot;">​</a></h3><p>导入是&quot;逆向工程&quot;的入口，由 <code>CodeGenerationAppService.ImportTableAsync</code> 闭环完成：</p><ol><li><strong>去重</strong>——同一目标表禁止重复配置（<code>TableName</code> 全局唯一）。</li><li><strong>扫描结构</strong>——<code>DatabaseSchemaImporter</code> 接通框架 <code>IDatabaseMetadataProvider</code>，只产出数据库层结构（列名/类型/可空/主键/自增/长度/小数位）。</li><li><strong>建表配置</strong>——类名默认由表名 <code>Pascalize</code>（<code>sys_user</code> → <code>SysUser</code>），可覆盖命名空间/模块/业务名/作者。</li><li><strong>建列配置</strong>——每列经 <code>ITypeMappingProvider.Map</code> 预填 C#/TS 类型、默认表单控件（<code>HtmlType</code>）与查询方式（<code>QueryType</code>），并写默认开关（<code>IsList=true</code> / <code>IsInsert=true</code> / <code>IsEdit=true</code> / <code>IsQuery=false</code>）。</li></ol><p>导入器有两处贴合本仓约定的健壮处理：</p><ul><li><strong>大小写还原</strong>：部分库（如 MySQL <code>lower_case_table_names=1</code>）返回全小写名，丢失驼峰。导入器反射已注册的 <code>[SugarTable]</code> 实体建名称目录，把 <code>syscodegendatasource</code> 还原为 <code>SysCodeGenDataSource</code>；未注册的外部表保持原样。</li><li><strong>分表折叠</strong>：带 <code>[SplitTable]</code> 的日志类实体物理表按时间分片（如 <code>sysdifflog_20260601</code>）。列表时把同实体的所有分片折叠为基础逻辑名（<code>SysDiffLog</code>）去重；导入基础名时自动扫最近一个分片取列结构。</li></ul><h3 id="字段配置" tabindex="-1">字段配置 <a class="header-anchor" href="#字段配置" aria-label="Permalink to &quot;字段配置&quot;">​</a></h3><p><code>SysCodeGenTableColumn</code> 是列级精细控制面，模板据此渲染。常用字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>CSharpType</code> / <code>CSharpProperty</code> / <code>TsType</code></td><td>类型与属性名映射（导入预填、可手改）</td></tr><tr><td><code>HtmlType</code></td><td>表单控件：<code>Input</code> / <code>Textarea</code> / <code>Select</code> / <code>Switch</code> / <code>DatePicker</code> / <code>InputNumber</code> / <code>TreeSelect</code> …</td></tr><tr><td><code>QueryType</code></td><td>查询方式：<code>Equal</code> / <code>Like</code> / <code>Between</code> / <code>In</code> …</td></tr><tr><td><code>IsList</code> / <code>IsInsert</code> / <code>IsEdit</code> / <code>IsQuery</code></td><td>列表显示 / 新增 / 编辑 / 查询开关</td></tr><tr><td><code>IsRequired</code> / <code>ColumnLength</code> / <code>MinValue</code> / <code>MaxValue</code> / <code>RegexPattern</code></td><td>表单校验约束</td></tr></tbody></table><p><strong>字典三分</strong>（选项列的可选项来源，由 <code>DictSelectorType</code> 决定生效字段）：</p><table tabindex="0"><thead><tr><th><code>DictSelectorType</code></th><th>生效字段</th><th>含义</th></tr></thead><tbody><tr><td><code>DictSelector</code></td><td><code>DictCode</code></td><td>关联系统字典类型编码</td></tr><tr><td><code>EnumSelector</code></td><td><code>EnumTypeName</code></td><td>关联枚举全名</td></tr><tr><td><code>ConstSelector</code></td><td><code>ConstValues</code></td><td>内联常量项 JSON</td></tr></tbody></table><blockquote><p><strong>字典三分是纯表单渲染信息，不入生成的领域代码</strong>——它只让前端页把某列渲染成对应下拉/选项，不产生任何跨表关联或外键。</p></blockquote><h2 id="模板-基于-scriban-可自定义" tabindex="-1">模板：基于 Scriban，可自定义 <a class="header-anchor" href="#模板-基于-scriban-可自定义" aria-label="Permalink to &quot;模板：基于 Scriban，可自定义&quot;">​</a></h2><p>模板存在 <code>SysCodeGenTemplate.TemplateContent</code>（BigString）。内置模板由 <code>SysCodeGenTemplateSeeder</code> 把 <code>Templates/Backend/*.sbn</code>、<code>Templates/Frontend/*.sbn</code>（编译为嵌入资源）种入库、标 <code>IsBuiltIn=true</code>；用户可新增自定义模板或改动非内置模板。</p><h3 id="模板变量" tabindex="-1">模板变量 <a class="header-anchor" href="#模板变量" aria-label="Permalink to &quot;模板变量&quot;">​</a></h3><p>引擎把 <code>CodeGenerationContext</code> 投影成 PascalCase 键的 Scriban 变量。顶层常用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ClassName          实体类名（如 SysProduct）</span></span>
<span class="line"><span>ClassNameCamel     camelCase（sysProduct）— 前端标识/API 对象名</span></span>
<span class="line"><span>ClassNameKebab     kebab-case（sys-product）— 前端文件名/路由</span></span>
<span class="line"><span>TableName          数据库表名</span></span>
<span class="line"><span>TableComment       表注释</span></span>
<span class="line"><span>Namespace / ModuleName / BusinessName / FunctionName / Author</span></span>
<span class="line"><span>TemplateType       枚举以名称字符串透出（&quot;Single&quot;/&quot;Tree&quot;/&quot;MasterDetail&quot;）</span></span>
<span class="line"><span>PrimaryKey         主键列（字典）</span></span>
<span class="line"><span>Columns            列集合（字典列表）</span></span>
<span class="line"><span>Options            扩展键（树/主从结构字段、ParentMenuId 等）</span></span></code></pre></div><p>每个 <code>Columns</code> 项（字典）常用键：<code>ColumnName</code> / <code>ColumnComment</code> / <code>CSharpType</code> / <code>CSharpProperty</code> / <code>TsProperty</code>（camelCase，对应后端 camelCase JSON）/ <code>TsType</code> / <code>IsPrimaryKey</code> / <code>IsNullable</code> / <code>IsRequired</code> / <code>HtmlType</code> / <code>QueryType</code> / <code>DictSelectorType</code> / <code>DictCode</code>，以及关键的 <strong><code>IsBaseColumn</code></strong>。</p><blockquote><p><code>IsBaseColumn</code> 标记基类 <code>BasicAppFullAuditedEntity</code> 托管的列（<code>BasicId</code> / <code>TenantId</code> / <code>IsDeleted</code> / 审计四段 / 软删三段）。模板据它跳过这些列，只生成业务属性——否则会重复声明基类已有成员。内置 <code>Entity.sbn</code> 里可见 <code>{{~ if !col.IsBaseColumn ~}}</code> 的用法。</p></blockquote><h3 id="文件名-路径表达式" tabindex="-1">文件名 / 路径表达式 <a class="header-anchor" href="#文件名-路径表达式" aria-label="Permalink to &quot;文件名 / 路径表达式&quot;">​</a></h3><p>模板另有两个表达式字段（本身也走 Scriban 渲染）：</p><ul><li><code>FileNameExpression</code>——输出文件名，如 <code>{{ ClassName }}Dtos.cs</code>；渲染失败或为空时回退 <code>ClassName</code> + <code>FileExtension</code>。</li><li><code>FilePathExpression</code>——输出目录（相对路径），拼在文件名前；渲染失败回退无目录输出。</li></ul><h3 id="约定-1-生成代码不焊外键关联" tabindex="-1">约定 ①：生成代码不焊外键关联 <a class="header-anchor" href="#约定-1-生成代码不焊外键关联" aria-label="Permalink to &quot;约定 ①：生成代码不焊外键关联&quot;">​</a></h3><p><strong>生成的代码不建立任何物理/对象层外键关联</strong>——没有 SqlSugar <code>Navigate</code> 导航属性、没有 LEFT JOIN、没有物理外键、没有跨表&quot;显示属性&quot;。跨表关联一律由业务层手写。上文的字典三分（<code>DictSelector</code> / <code>EnumSelector</code> / <code>ConstSelector</code>）保留，但它只是<strong>表单选项来源</strong>，同样不入生成代码。这与代码生成器的既定方向一致：生成物保持自包含、无隐式耦合，关联关系交给人显式表达。</p><h3 id="约定-2-用原生-scriban-而非框架-itemplateservice" tabindex="-1">约定 ②：用原生 Scriban，而非框架 <code>ITemplateService</code> <a class="header-anchor" href="#约定-2-用原生-scriban-而非框架-itemplateservice" aria-label="Permalink to &quot;约定 ②：用原生 Scriban，而非框架 \`ITemplateService\`&quot;">​</a></h3><p>渲染由 <code>ScribanTemplateRenderer</code> 直接用<strong>原生 Scriban</strong> 完成：<code>Template.Parse(...)</code> 解析、<code>ScriptObject</code> 注入变量、<code>TemplateContext</code> 渲染，并关闭成员重命名（<code>MemberRenamer = member =&gt; member.Name</code>），使模板以确定的 PascalCase 访问变量。</p><p>它<strong>刻意不走</strong>框架的 <code>ITemplateService</code>——后者对 <code>string</code> 的默认引擎是<strong>简单替换引擎，不解析 Scriban 语法</strong>（<code>{{ }}</code>、<code>for</code>、<code>if</code>），会把模板原样输出。要真正跑 Scriban 语法就必须绕开它、用原生 Scriban。这一点在 <code>ScribanTemplateRenderer</code> 的注释里有明确说明。渲染前可用 <code>Validate</code> 做语法校验（<code>Template.Parse</code> 报错即返回 <code>TemplateRenderValidation.Invalid</code>）。</p><blockquote><p>枚举移除了 Razor（需运行时编译、框架不支持，避免&quot;选了报错&quot;的伪能力）；<code>T4</code> 在枚举中保留占位，但解析器目前只注册了 Scriban，选其它引擎会抛 <code>NotSupportedException</code>。</p></blockquote><h2 id="生成流程" tabindex="-1">生成流程 <a class="header-anchor" href="#生成流程" aria-label="Permalink to &quot;生成流程&quot;">​</a></h2><p>对外方法（<code>CodeGenerationAppService</code>，经 <code>[DynamicApi]</code> 暴露，分组 <code>BasicApp.CodeGen</code>）与权限：</p><table tabindex="0"><thead><tr><th>步骤</th><th>方法</th><th>权限码</th></tr></thead><tbody><tr><td>列库表</td><td><code>ListDatabaseTablesAsync</code></td><td><code>code_gen:read</code></td></tr><tr><td>导入表结构</td><td><code>ImportTableAsync</code></td><td><code>code_gen:import</code></td></tr><tr><td>预览</td><td><code>PreviewAsync</code></td><td><code>code_gen:read</code></td></tr><tr><td>执行生成</td><td><code>GenerateAsync</code></td><td><code>code_gen:execute</code></td></tr></tbody></table><p>端到端流程：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>填写 ConnectionConfigId（框架已注册连接，留空用主库）</span></span>
<span class="line"><span>  → 列出库表、导入目标表         [ImportTableAsync]</span></span>
<span class="line"><span>      · 扫结构 + 类型映射 → 落表/列配置</span></span>
<span class="line"><span>  → 调整表配置（模板类型/命名空间/模块）与列配置（控件/查询/字典三分）</span></span>
<span class="line"><span>  → 预览                          [PreviewAsync → GenType.Preview]</span></span>
<span class="line"><span>      · 建 CodeGenerationContext → 逐模板渲染 → 返回产物清单（含内容）</span></span>
<span class="line"><span>  → 执行生成                      [GenerateAsync]</span></span>
<span class="line"><span>      · 同渲染核心，再按 GenType 分流产出</span></span>
<span class="line"><span>      · 无论成败写一条 SysCodeGenHistory 留痕</span></span></code></pre></div><p>生成方式由 <code>GenType</code> 决定：</p><table tabindex="0"><thead><tr><th><code>GenType</code></th><th>行为</th></tr></thead><tbody><tr><td><code>Zip</code></td><td>生成并下载：打成 Zip，包体以 <strong>Base64</strong> 随 <code>CodeGenResultDto.PackageBase64</code> 返回，前端触发下载</td></tr><tr><td><code>Project</code></td><td>生成到项目：后端产物写进与表配置<strong>命名空间</strong>同名的模块项目，前端产物写进前端工程</td></tr></tbody></table><p>预览走独立入口（<code>PreviewAsync</code>），只返回产物清单（含文件内容），不打包不落盘。</p><h3 id="生成到项目的位置" tabindex="-1">生成到项目的位置 <a class="header-anchor" href="#生成到项目的位置" aria-label="Permalink to &quot;生成到项目的位置&quot;">​</a></h3><p>写入位置不由表配置随意指定，而是按宿主内容根（WebHost 项目目录）推导本仓库的目录：</p><ul><li><strong>后端</strong>：在 <code>BackendRootPath</code>（缺省配置 <code>../..</code>，即 <code>backend/src</code>）下的分组目录里找 <code>&lt;命名空间&gt;/&lt;命名空间&gt;.csproj</code>，如命名空间 <code>XiHan.BasicApp.Sample</code> 写进 <code>backend/src/business/XiHan.BasicApp.Sample/</code>。模板的路径表达式（<code>Domain/Entities</code>、<code>Application/Dtos</code>…）与接线产物都相对这个项目目录。</li><li><strong>前端</strong>：写进 <code>FrontendRootPath</code>（缺省配置 <code>../../../../frontend</code>）指向的前端工程，模板路径 <code>src/api/modules/&lt;module&gt;/</code>、<code>src/views/&lt;module&gt;/&lt;class-kebab&gt;/</code> 相对它。</li><li>产物按模板分组归属：<code>backend-*</code> 进后端项目，<code>frontend-*</code> 进前端工程；生成范围只选后端时不碰前端配置。</li></ul><p>由 <code>ProjectArtifactWriter</code> 写入，绑定配置节 <code>CodeGeneration</code>（<code>CodeGenerationOptions</code>），<strong>默认关闭</strong>，任一条件不满足即整体拒绝、一个文件都不写：</p><ul><li><code>EnableGenerateToProject</code> 未开启（缺省）→ 拒绝。配置只放在 <code>appsettings.Development.json</code>，其他环境只能生成并下载。</li><li>命名空间为空、不是以点分隔的标识符，或在源码根下找不到 / 找到多个同名项目 → 拒绝，不替你新建项目。</li><li>前端工程目录下没有 <code>package.json</code> → 拒绝。</li><li>模板分组既不是后端也不是前端 → 拒绝（不知道写进哪个项目）。</li><li>产物相对路径是绝对路径 / 带盘符 / 拼接后越界（<code>..</code> 逃逸）→ 拒绝。</li></ul><p>全部产物定好位置才动磁盘；手动文件已存在时跳过，生成历史记下写入的项目目录。</p><h3 id="沿用已有实体" tabindex="-1">沿用已有实体 <a class="header-anchor" href="#沿用已有实体" aria-label="Permalink to &quot;沿用已有实体&quot;">​</a></h3><p>本仓库的表一般由实体自动建出：先写实体，启动时框架按实体建表，再把表导入代码生成。这种表在代码里已经有实体，生成时沿用它：</p><ul><li>引擎经实体元数据目录按表名找到实体类型；它没有生成器标记（<code>[GeneratedCode(&quot;XiHan.CodeGen&quot;, …)]</code>）即视为手写实体，不再生成 <code>backend.entity</code> 与 <code>backend.entity.manual</code>。</li><li>仓储、映射、查询服务等按实体所在命名空间引用它（模板变量 <code>EntityNamespace</code>）；表配置的类名须与实体类名一致，否则生成直接失败并给出正确类名。</li><li>关联目标表已有实体时，选项查询直接用它的真实类型。</li><li>外部库的表没有实体，照常生成实体；生成的实体带生成器标记，下次照常覆盖。</li><li>唯一列的索引由实体负责：沿用已有实体时要自己在实体上加 <code>SugarIndex</code>。</li><li>生成到项目时，若项目里已有手写的同名文件（如手写仓储）而没有对应的自动文件，整体拒绝、一个文件都不写：先移走它，自定义代码写进生成后的手动文件。</li></ul><h2 id="零代码运行时-只读" tabindex="-1">零代码运行时（只读） <a class="header-anchor" href="#零代码运行时-只读" aria-label="Permalink to &quot;零代码运行时（只读）&quot;">​</a></h2><p><code>DynamicRuntimeAppService</code> 提供一条与&quot;生成代码&quot;平行的轻量路径：给定一张<strong>已配置且启用</strong>的 <code>SysCodeGenTable</code>，不生成/不编译任何实体代码，直接按其列配置解释执行：</p><table tabindex="0"><thead><tr><th>方法</th><th>行为</th><th>权限码</th></tr></thead><tbody><tr><td><code>GetSchemaAsync</code></td><td>按 <code>SysCodeGenTableColumn</code> 投影字段 schema（属性名、标签、<code>TsType</code>/<code>HtmlType</code>/<code>QueryType</code>、列表/查询/必填开关）</td><td><code>code_gen:read</code></td></tr><tr><td><code>GetPageAsync</code></td><td>用 <code>ISqlSugarClientResolver.GetCurrentClient()</code> 对表名做动态分页查询（<code>Queryable&lt;Dictionary&lt;string, object&gt;&gt;().AS(tableName)</code>）</td><td><code>code_gen:read</code></td></tr></tbody></table><p>表名只取自已配置且启用（<code>Status = Enabled</code>）的 <code>SysCodeGenTable</code> 记录，从不直接拼接用户传入的表名字符串，因此没有 SQL 注入面；未启用的表配置访问会抛友好异常。当前只做 schema + 列表（只读），写入/DDL 未开放。前端&quot;查看运行时数据&quot;弹窗（表格行操作）即消费这两个接口，适合在正式生成代码前先验证列配置是否符合预期。</p><h2 id="扩展与二次开发" tabindex="-1">扩展与二次开发 <a class="header-anchor" href="#扩展与二次开发" aria-label="Permalink to &quot;扩展与二次开发&quot;">​</a></h2><ul><li><strong>加一种数据库方言</strong>：扩展 <code>ITypeMappingProvider</code> 的映射；扫描能力依赖框架 <code>IDatabaseMetadataProvider</code>。</li><li><strong>加/改模板</strong>：新增 <code>SysCodeGenTemplate</code>（自定义编码、Scriban 正文、文件名/路径表达式），或改动非内置模板；用模板变量表与 <code>IsBaseColumn</code> 约定编写。</li><li><strong>换渲染引擎</strong>：实现 <code>ITemplateRenderer</code>（<code>Engine</code> 返回对应 <code>TemplateEngine</code>）并注册，<code>TemplateRendererResolver</code> 后注册覆盖先注册。</li><li><strong>生成后并入源码</strong>：按 <code>_GeneratedMenuPermission/README.md</code> 确认权限码常量与两个登记类落位，重启后端即由汇总种子写入权限与菜单（不需要登记种子）；旧版本生成的 <code>XxxPermissionSeeder</code> / <code>XxxMenuSeeder</code> 及其 <code>AddDataSeeder</code> 登记要删掉。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="https://framework.docs.xihanfun.com/packages/templating" target="_blank" rel="noreferrer">框架 · 模板模块</a>：框架 <code>ITemplateService</code> 的定位与简单替换引擎（为何代码生成绕开它用原生 Scriban）。</li><li><a href="https://framework.docs.xihanfun.com/guide/dynamic-api" target="_blank" rel="noreferrer">框架 · 动态 API</a>：<code>[DynamicApi]</code> 如何把 <code>CodeGenerationAppService</code> 暴露为 REST。</li><li><a href="./permission">权限模型</a>：<code>code_gen:*</code> 权限码、菜单即绑与二阶产物落地的背景。</li><li><a href="./introduction">系统架构</a>：模块在启动聚合中的装配位置。</li></ul>`,84)])])}const b=d(a,[["render",r]]);export{u as __pageData,b as default};
